import pandas as pd

def clean(df):
    df = df.copy()
    # Normalize Category (strip extra spaces) - fixes 'Furniture ', ' Furniture', 'Accessories '
    if 'Category' in df.columns:
        df['Category'] = df['Category'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # Normalize Region and fix typos Suoth->South, Nort->North
    if 'Region' in df.columns:
        df['Region'] = df['Region'].apply(lambda x: x.strip() if isinstance(x, str) else x)
        df['Region'] = df['Region'].replace({'Suoth': 'South', 'Nort': 'North'})
    # Ensure numeric types (handles text numbers if present)
    for c in ['Order_ID', 'Quantity', 'Price', 'Revenue']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    # Fix invalid dates (coerce errors to NaT)
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    # Enforce Revenue = Quantity * Price
    if 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = df['Quantity'] * df['Price']
    # Deduplicate on Order_ID (unique order number)
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'])
    return df

def answer(df):
    # total revenue by category
    if 'Category' not in df.columns or 'Revenue' not in df.columns:
        return {}
    d = df.dropna(subset=['Category'])
    # keep only allowed categories after cleaning (optional)
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    # d = d[d['Category'].isin(allowed)]
    grouped = d.groupby('Category', dropna=True)['Revenue'].sum()
    # convert to regular dict with float/int values
    result = {str(k): float(v) for k, v in grouped.items()}
    return result
